from solution import Entry, Report, solve

assert solve([], 0) == Report(0, 0, 0), 'fixture 0'
assert solve([], 5) == Report(0, 1, 5), 'fixture 1'
assert solve([], 1) == Report(0, 1, 1), 'fixture 2'
assert solve([Entry(11, 15)], 2) == Report(0, 1, 2), 'fixture 3'
assert solve([Entry(3, 8), Entry(6, 12)], 3) == Report(0, 1, 3), 'fixture 4'
assert solve([Entry(10, 13), Entry(0, 2), Entry(1, 6)], 4) == Report(4, 0, 0), 'fixture 5'
assert solve([Entry(3, 6), Entry(5, 10), Entry(7, 8), Entry(6, 13)], 5) == Report(2, 1, 3), 'fixture 6'
assert solve([Entry(0, 5), Entry(9, 12), Entry(6, 7), Entry(4, 5), Entry(8, 15)], 6) == Report(5, 1, 1), 'fixture 7'
assert solve([Entry(1, 8), Entry(7, 13), Entry(5, 9), Entry(10, 14), Entry(9, 11), Entry(0, 2)], 7) == Report(7, 0, 0), 'fixture 8'
assert solve([Entry(1, 5), Entry(0, 1), Entry(6, 12), Entry(11, 12), Entry(7, 14), Entry(5, 12), Entry(0, 3)], 8) == Report(8, 0, 0), 'fixture 9'
assert solve([Entry(10, 14), Entry(10, 17), Entry(7, 8), Entry(9, 11), Entry(11, 12), Entry(9, 12), Entry(2, 3), Entry(3, 9)], 1) == Report(0, 1, 1), 'fixture 10'
assert solve([Entry(2, 9), Entry(5, 7), Entry(4, 6), Entry(4, 11), Entry(5, 9), Entry(10, 11), Entry(0, 4), Entry(6, 11), Entry(3, 4)], 2) == Report(2, 0, 0), 'fixture 11'
assert solve([Entry(7, 8), Entry(2, 7), Entry(1, 7), Entry(11, 14), Entry(9, 12), Entry(5, 8), Entry(8, 11), Entry(2, 4), Entry(4, 6), Entry(8, 11)], 3) == Report(2, 1, 1), 'fixture 12'
assert solve([Entry(6, 12), Entry(0, 2), Entry(7, 9), Entry(4, 5), Entry(6, 8), Entry(8, 14), Entry(9, 14), Entry(9, 14), Entry(3, 7), Entry(2, 8), Entry(7, 11)], 4) == Report(4, 0, 0), 'fixture 13'
assert solve([Entry(9, 12), Entry(5, 12), Entry(3, 8), Entry(5, 7), Entry(4, 6), Entry(9, 10), Entry(1, 8), Entry(11, 15), Entry(6, 10), Entry(8, 9), Entry(1, 6), Entry(6, 12)], 5) == Report(4, 1, 1), 'fixture 14'
assert solve([], 6) == Report(0, 1, 6), 'fixture 15'
assert solve([Entry(1, 3)], 7) == Report(2, 2, 4), 'fixture 16'
assert solve([Entry(0, 4), Entry(2, 5)], 8) == Report(5, 1, 3), 'fixture 17'
assert solve([Entry(8, 10), Entry(7, 10), Entry(7, 9)], 1) == Report(0, 1, 1), 'fixture 18'
assert solve([Entry(4, 9), Entry(8, 12), Entry(0, 3), Entry(8, 15)], 2) == Report(2, 0, 0), 'fixture 19'
assert solve([Entry(10, 12), Entry(10, 11), Entry(6, 9), Entry(10, 14), Entry(8, 9)], 3) == Report(0, 1, 3), 'fixture 20'
assert solve([Entry(5, 9), Entry(3, 7), Entry(4, 10), Entry(9, 16), Entry(10, 12), Entry(9, 16)], 4) == Report(1, 1, 3), 'fixture 21'
assert solve([Entry(3, 8), Entry(3, 5), Entry(0, 6), Entry(2, 9), Entry(8, 13), Entry(8, 10), Entry(10, 11)], 5) == Report(5, 0, 0), 'fixture 22'
assert solve([Entry(7, 14), Entry(8, 15), Entry(2, 9), Entry(10, 11), Entry(3, 5), Entry(5, 7), Entry(10, 12), Entry(4, 9)], 6) == Report(4, 1, 2), 'fixture 23'
assert solve([Entry(0, 3), Entry(3, 5)], 5) == Report(5, 0, 0), 'fixture 24'
assert solve([Entry(9, 12)], 5) == Report(0, 1, 5), 'fixture 25'
assert solve([Entry(0, 1), Entry(4, 5)], 5) == Report(2, 1, 3), 'fixture 26'
assert solve([Entry(1, 3), Entry(2, 4), Entry(6, 9)], 8) == Report(5, 2, 2), 'fixture 27'
